CREATE OR REPLACE VIEW Mng_VCurnHist As
SELECT
       C.Id        Curn_Id    ,
       C.Name      Curn_Name  ,
       C.Code      Curn_Code  ,
       C.Rate      Curn_Rate  ,
       C.HDate     Curn_ChDate,
       C.Status_Id Curn_Status,
       C.Rem       Curn_Rem   ,
       H.Id        CHist_Id   ,
       H.hDate     CHist_Date ,
       H.Rate      CHist_Rate ,
       H.Rem       CHist_Rem  ,
       H.Ins_User ,
       H.Ins_Date
  From Mng_Curn     C,
       Mng_CurnHist H
 Where H.Curn_Id=C.Id;

